function Get-ChatSelectQuery([string]$Tool) {
 switch($Tool){
    'get_recent_suppliers' {'WITH dated AS (SELECT s.BPSNUM_0,p.BPRNAM_0,s.ENAFLG_0 AS supplier_active,p.ENAFLG_0 AS partner_active,COALESCE(CASE WHEN s.CREDATTIM_0>CONVERT(datetime,''19000101'',112) THEN s.CREDATTIM_0 END,CASE WHEN s.CREDAT_0>CONVERT(datetime,''19000101'',112) THEN s.CREDAT_0 END) AS created_at,CASE WHEN s.CREDATTIM_0>CONVERT(datetime,''19000101'',112) THEN ''datetime'' ELSE ''date'' END AS date_precision FROM TEST.BPSUPPLIER s JOIN TEST.BPARTNER p ON p.BPRNUM_0=s.BPSNUM_0 WHERE (@Status=''all'' OR @Status=''inactive'' AND s.ENAFLG_0=1 AND p.ENAFLG_0=1 OR @Status=''active'' AND s.ENAFLG_0=2 AND p.ENAFLG_0=2)) SELECT TOP (CONVERT(int,@PageSize)) BPSNUM_0,BPRNAM_0,supplier_active,partner_active,CONVERT(nvarchar(23),created_at,121) AS created_at,date_precision,COUNT_BIG(*) OVER(PARTITION BY created_at) AS same_creation_time,(SELECT COUNT_BIG(*) FROM dated WHERE created_at IS NULL) AS unknown_creation_dates FROM dated WHERE created_at IS NOT NULL ORDER BY created_at DESC,BPSNUM_0'}
    'list_suppliers' {'SELECT s.BPSNUM_0,p.BPRNAM_0,s.ENAFLG_0 AS supplier_active,p.ENAFLG_0 AS partner_active,COUNT_BIG(*) OVER() AS total_count FROM TEST.BPSUPPLIER s JOIN TEST.BPARTNER p ON p.BPRNUM_0=s.BPSNUM_0 WHERE (@Status=''all'' OR @Status=''inactive'' AND s.ENAFLG_0=1 AND p.ENAFLG_0=1 OR @Status=''active'' AND s.ENAFLG_0=2 AND p.ENAFLG_0=2) ORDER BY s.BPSNUM_0 OFFSET CONVERT(int,@Offset) ROWS FETCH NEXT (CONVERT(int,@PageSize)+1) ROWS ONLY'}
    'get_supplier_creation_fields' {'SELECT t.name AS table_name,c.name AS column_name,TYPE_NAME(c.system_type_id) AS data_type,CASE WHEN c.system_type_id IN (231,239) THEN c.max_length/2 ELSE c.max_length END AS max_characters,c.is_nullable,c.is_computed,c.is_identity FROM sys.columns c JOIN sys.tables t ON t.object_id=c.object_id JOIN sys.schemas s ON s.schema_id=t.schema_id WHERE s.name=''TEST'' AND t.name IN (''BPARTNER'',''BPSUPPLIER'',''BPADDRESS'') AND c.name IN (''BPRNUM_0'',''BPRNAM_0'',''BPRSHO_0'',''XICE_0'',''XIF_0'',''XRC_0'',''BPSNUM_0'',''BPSNAM_0'',''PTE_0'',''BSGCOD_0'',''ACCCOD_0'',''VACBPR_0'',''CUR_0'',''BPAADDLIG_0'',''BPAADDLIG_1'',''BPAADDLIG_2'',''CTY_0'',''TEL_0'',''FAX_0'') ORDER BY t.name,c.column_id'}
    'search_customers' {'SELECT TOP (5) c.BPCNUM_0,p.BPRNAM_0,p.BPRNAM_1 FROM TEST.BPCUSTOMER c LEFT JOIN TEST.BPARTNER p ON p.BPRNUM_0=c.BPCNUM_0 WHERE (@Supplier<>'''' AND c.BPCNUM_0=@Supplier) OR (@Supplier='''' AND @Label<>'''' AND (p.BPRNAM_0 LIKE @Pattern ESCAPE ''~'' OR p.BPRNAM_1 LIKE @Pattern ESCAPE ''~'')) ORDER BY c.BPCNUM_0'}
    'search_articles' {'SELECT TOP (5) ITMREF_0,ITMDES1_0,TCLCOD_0,STU_0,PUU_0,SAU_0,ACCCOD_0,VACITM_0 FROM TEST.ITMMASTER WHERE ITMDES1_0 LIKE @Pattern ESCAPE ''~'' AND (@Category='''' OR TCLCOD_0=@Category) ORDER BY ITMREF_0'}
    'get_recent_articles' {'SELECT TOP (5) ITMREF_0,ITMDES1_0,TCLCOD_0,STU_0,ACCCOD_0,VACITM_0,CREDATTIM_0 FROM TEST.ITMMASTER WHERE (@Category='''' OR TCLCOD_0=@Category) ORDER BY CREDATTIM_0 DESC,ROWID DESC'}
    'get_article_record' {'SELECT ITMREF_0,ITMDES1_0,TCLCOD_0,ITMSTA_0,STU_0,PUU_0,SAU_0,PUUSTUCOE_0,SAUSTUCOE_0,ACCCOD_0,VACITM_0,VACITM_1,VACITM_2,STOMGTCOD_0,LOTMGTCOD_0 FROM TEST.ITMMASTER WHERE ITMREF_0=@Code'}
    'get_article_site_record' {'SELECT * FROM TEST.ITMFACILIT WHERE ITMREF_0=@Code AND STOFCY_0=@Site'}
    'check_article_duplicate' {'SELECT TOP (1) ITMREF_0,ITMDES1_0,TCLCOD_0,STU_0,PUU_0,SAU_0 FROM TEST.ITMMASTER WHERE ITMREF_0=@Code'}
    'get_article_categories' {'SELECT TCLCOD_0,TCLDES_0,STOFCY_0,STU_0,PUU_0,SAU_0,PUUSTUCOE_0,SAUSTUCOE_0,ACCCOD_0,VACITM_0,STOMGTCOD_0,LOTMGTCOD_0,ITMREFCOU_0 FROM TEST.ITMCATEG WHERE (@Category='''' OR TCLCOD_0=@Category) AND (@Label='''' OR TCLDES_0 COLLATE Latin1_General_CI_AI LIKE @Pattern ESCAPE ''~'' OR TCLDES_0 COLLATE Latin1_General_CI_AI LIKE @NearPattern ESCAPE ''~'' OR TCLCOD_0 COLLATE Latin1_General_CI_AI LIKE @Pattern ESCAPE ''~'') AND (@Site='''' OR STOFCY_0=@Site OR LTRIM(RTRIM(STOFCY_0))='''') ORDER BY CASE WHEN STOFCY_0=@Site AND @Site<>'''' THEN 0 ELSE 1 END,TCLCOD_0,STOFCY_0'}
    'get_units' {'SELECT TOP (3) UOM_0,UOMDEC_0,UOMSYM_0 FROM TEST.TABUNIT WHERE UOM_0 IN (@Unit,@Unit2) ORDER BY UOM_0'}
    'search_units' {'SELECT TOP (250) u.UOM_0,u.UOMDEC_0,u.UOMSYM_0,t.TEXTE_0 AS label FROM TEST.TABUNIT u LEFT JOIN TEST.ATEXTRA t ON t.CODFIC_0=''TABUNIT'' AND t.IDENT1_0=u.UOM_0 AND LTRIM(RTRIM(t.IDENT2_0))='''' AND t.LANGUE_0=''FRA'' WHERE @Label='''' OR u.UOM_0 COLLATE Latin1_General_CI_AI LIKE @Pattern ESCAPE ''~'' OR t.TEXTE_0 COLLATE Latin1_General_CI_AI LIKE @Pattern ESCAPE ''~'' OR t.TEXTE_0 COLLATE Latin1_General_CI_AI LIKE @NearPattern ESCAPE ''~'' ORDER BY u.UOM_0,t.ZONE_0'}
    'get_unit_conversions' {'SELECT TOP (3) UOM1_0,UOM2_0,COEUOM_0,REV_0 FROM TEST.TABCOEFF WHERE (UOM1_0=@Unit AND UOM2_0=@Unit2) OR (UOM1_0=@Unit2 AND UOM2_0=@Unit) ORDER BY UOM1_0'}
    'get_sites' {'SELECT TOP (51) f.FCY_0,f.FCYNAM_0,f.LEGCPY_0,c.CPYNAM_0,f.CRY_0,f.WRHFLG_0,f.PURFLG_0,f.SALFLG_0 FROM TEST.FACILITY f LEFT JOIN TEST.COMPANY c ON c.CPY_0=f.LEGCPY_0 WHERE @Site='''' OR f.FCY_0=@Site ORDER BY f.FCY_0'}
    'search_suppliers' {'SELECT TOP (21) s.BPSNUM_0,p.BPRNAM_0,p.BPRNAM_1 FROM TEST.BPSUPPLIER s LEFT JOIN TEST.BPARTNER p ON p.BPRNUM_0=s.BPSNUM_0 WHERE (@Supplier<>'''' AND s.BPSNUM_0=@Supplier) OR (@Supplier='''' AND @Label<>'''' AND (p.BPRNAM_0 COLLATE Latin1_General_100_CI_AI LIKE @Pattern ESCAPE ''~'' OR p.BPRNAM_1 COLLATE Latin1_General_100_CI_AI LIKE @Pattern ESCAPE ''~'' OR p.BPRNAM_0 COLLATE Latin1_General_100_CI_AI LIKE @NearPattern ESCAPE ''~'')) ORDER BY CASE WHEN p.BPRNAM_0 COLLATE Latin1_General_100_CI_AI=@Label THEN 0 WHEN p.BPRNAM_0 COLLATE Latin1_General_100_CI_AI LIKE @Pattern ESCAPE ''~'' THEN 1 ELSE 2 END,s.BPSNUM_0'}
    'search_supplier_candidates' {'SELECT TOP (21) s.BPSNUM_0,p.BPRNAM_0,p.BPRNAM_1 FROM TEST.BPSUPPLIER s JOIN TEST.BPARTNER p ON p.BPRNUM_0=s.BPSNUM_0 WHERE LEN(@Label) BETWEEN 3 AND 60 AND ABS(LEN(RTRIM(p.BPRNAM_0))-LEN(@Label))<=6 AND DIFFERENCE(p.BPRNAM_0 COLLATE Latin1_General_100_CI_AI,@Label COLLATE Latin1_General_100_CI_AI)>=3 ORDER BY DIFFERENCE(p.BPRNAM_0 COLLATE Latin1_General_100_CI_AI,@Label COLLATE Latin1_General_100_CI_AI) DESC,ABS(LEN(RTRIM(p.BPRNAM_0))-LEN(@Label)),s.BPSNUM_0'}
    'get_supplier_article_references' {'SELECT TOP (5) ITMREF_0,BPSNUM_0,ITMREFBPS_0,PUU_0,PUUSTUCOE_0 FROM TEST.ITMBPS WHERE BPSNUM_0=@Supplier AND (@Code='''' OR ITMREF_0=@Code) ORDER BY ITMREF_0'}
    'get_accounting_categories' {'SELECT TOP (5) TYP_0,ACCCOD_0,COA_0,DES_0 FROM TEST.GACCCODE WHERE TYP_0=1 AND ((@Code<>'''' AND ACCCOD_0=@Code) OR (@Code='''' AND @Label<>'''' AND DES_0 LIKE @Pattern ESCAPE ''~'')) ORDER BY ACCCOD_0,COA_0'}
    'get_tax_rules' {'SELECT TOP (10) r.VAT_0,r.CPY_0,r.LEG_0,r.STRDAT_0,r.VATRAT_0,v.VATDES_0 FROM TEST.TABRATVAT r JOIN TEST.TABVAT v ON v.VAT_0=r.VAT_0 AND v.LEG_0=r.LEG_0 WHERE (@Code='''' OR r.VAT_0=@Code) AND (@Rate='''' OR r.VATRAT_0=TRY_CONVERT(decimal(9,3),@Rate)) AND r.STRDAT_0<=CAST(GETDATE() AS date) AND (@Company='''' OR r.CPY_0 IN (@Company,'''')) ORDER BY r.STRDAT_0 DESC,r.VAT_0'}
    'get_tax_determination_by_vat' {'SELECT COD_0,LEG_0,ENAFLG_0,VACITM_0,VACBPR_0,VAT_0,VACDES_0 FROM TEST.TABVAC WHERE VAT_0=@Code ORDER BY COD_0'}
    'get_tax_determination' {'SELECT TOP (5) COD_0,LEG_0,ENAFLG_0,VACITM_0,VACBPR_0,VAT_0,VACDES_0 FROM TEST.TABVAC WHERE VACITM_0=@Level ORDER BY COD_0'}
    'get_article_site' {'SELECT TOP (1) ITMREF_0,STOFCY_0 FROM TEST.ITMFACILIT WHERE ITMREF_0=@Code AND STOFCY_0=@Site'}
    'get_supplier_record' {'SELECT ''TEST'' AS folder,p.BPRNUM_0,p.BPRNAM_0,p.BPRSHO_0,p.XICE_0,p.XIF_0,p.XRC_0,p.ENAFLG_0 AS partner_active,p.CRY_0,p.CUR_0,s.BPSNUM_0,s.BPSNAM_0,s.BPSSHO_0,s.ENAFLG_0 AS supplier_active,s.BSGCOD_0,s.PTE_0,s.VACBPR_0,s.ACCCOD_0,s.BPAADD_0,a.CTY_0,a.TEL_0,a.BPAADDLIG_0,a.BPAADDLIG_1,a.BPAADDLIG_2 FROM TEST.BPARTNER p JOIN TEST.BPSUPPLIER s ON s.BPSNUM_0=p.BPRNUM_0 LEFT JOIN TEST.BPADDRESS a ON a.BPATYP_0=1 AND a.BPANUM_0=s.BPSNUM_0 AND a.BPAADD_0=s.BPAADD_0 WHERE @Folder=''TEST'' AND p.BPRNUM_0=@Supplier UNION ALL SELECT ''OB'' AS folder,p.BPRNUM_0,p.BPRNAM_0,p.BPRSHO_0,p.XICE_0,p.XIF_0,p.XRC_0,p.ENAFLG_0 AS partner_active,p.CRY_0,p.CUR_0,s.BPSNUM_0,s.BPSNAM_0,s.BPSSHO_0,s.ENAFLG_0 AS supplier_active,s.BSGCOD_0,s.PTE_0,s.VACBPR_0,s.ACCCOD_0,s.BPAADD_0,a.CTY_0,a.TEL_0,a.BPAADDLIG_0,a.BPAADDLIG_1,a.BPAADDLIG_2 FROM OB.BPARTNER p JOIN OB.BPSUPPLIER s ON s.BPSNUM_0=p.BPRNUM_0 LEFT JOIN OB.BPADDRESS a ON a.BPATYP_0=1 AND a.BPANUM_0=s.BPSNUM_0 AND a.BPAADD_0=s.BPAADD_0 WHERE @Folder=''OB'' AND p.BPRNUM_0=@Supplier'}
    'check_supplier_fiscal_duplicates' {'SELECT ''TEST'' AS folder,p.BPRNUM_0,p.BPRNAM_0,p.XICE_0,p.XIF_0,p.XRC_0,p.ENAFLG_0 AS partner_active,p.BPSFLG_0,s.BPSNUM_0,s.BPSNAM_0,s.BPSSHO_0,s.ENAFLG_0 AS supplier_active FROM TEST.BPARTNER p LEFT JOIN TEST.BPSUPPLIER s ON s.BPSNUM_0=p.BPRNUM_0 WHERE @Folder=''TEST'' AND ((@Ice<>'''' AND p.XICE_0=@Ice) OR (@Fiscal<>'''' AND p.XIF_0=@Fiscal) OR (@Rc<>'''' AND p.XRC_0=@Rc) OR (@Supplier<>'''' AND p.BPRNUM_0=@Supplier) OR (@Label<>'''' AND (p.BPRNAM_0 LIKE @Pattern ESCAPE ''~'' OR s.BPSNAM_0 LIKE @Pattern ESCAPE ''~''))) UNION ALL SELECT ''OB'' AS folder,p.BPRNUM_0,p.BPRNAM_0,p.XICE_0,p.XIF_0,p.XRC_0,p.ENAFLG_0 AS partner_active,p.BPSFLG_0,s.BPSNUM_0,s.BPSNAM_0,s.BPSSHO_0,s.ENAFLG_0 AS supplier_active FROM OB.BPARTNER p LEFT JOIN OB.BPSUPPLIER s ON s.BPSNUM_0=p.BPRNUM_0 WHERE @Folder=''OB'' AND ((@Ice<>'''' AND p.XICE_0=@Ice) OR (@Fiscal<>'''' AND p.XIF_0=@Fiscal) OR (@Rc<>'''' AND p.XRC_0=@Rc) OR (@Supplier<>'''' AND p.BPRNUM_0=@Supplier) OR (@Label<>'''' AND (p.BPRNAM_0 LIKE @Pattern ESCAPE ''~'' OR s.BPSNAM_0 LIKE @Pattern ESCAPE ''~'')))'}
    'get_supplier_preparation_profile' {'SELECT ''TEST'' AS folder,c.BSGCOD_0,c.CRY_0,c.CUR_0,c.PTE_0,c.VACBPR_0,c.ACCCOD_0,c.REFCOU_0,c.CREMOD_0,CASE WHEN EXISTS(SELECT 1 FROM TEST.TABCUR v WHERE v.CUR_0=c.CUR_0) THEN 1 ELSE 0 END AS currency_verified,CASE WHEN EXISTS(SELECT 1 FROM TEST.TABCOUNTRY v WHERE v.CRY_0=c.CRY_0) THEN 1 ELSE 0 END AS country_verified,CASE WHEN EXISTS(SELECT 1 FROM TEST.TABPAYTERM v WHERE v.PTE_0=c.PTE_0) THEN 1 ELSE 0 END AS payment_verified,CASE WHEN EXISTS(SELECT 1 FROM TEST.TABVACBPR v WHERE v.VACBPR_0=c.VACBPR_0 AND v.ENAFLG_0=2) THEN 1 ELSE 0 END AS tax_regime_verified,CASE WHEN EXISTS(SELECT 1 FROM TEST.GACCCODE v WHERE v.ACCCOD_0=c.ACCCOD_0 AND v.TYP_0=3) THEN 1 ELSE 0 END AS accounting_verified,proposal.code AS candidate_code,CASE WHEN LEN(proposal.code)<=15 AND NOT EXISTS(SELECT 1 FROM TEST.BPARTNER p WHERE p.BPRNUM_0=proposal.code) AND NOT EXISTS(SELECT 1 FROM TEST.BPSUPPLIER s WHERE s.BPSNUM_0=proposal.code) THEN 1 ELSE 0 END AS candidate_available FROM TEST.BPSCATEG c OUTER APPLY (SELECT MAX(n) AS highest FROM (SELECT TRY_CONVERT(bigint,SUBSTRING(RTRIM(BPRNUM_0),2,14)) n FROM TEST.BPARTNER WHERE BPRNUM_0 LIKE ''F%'' UNION ALL SELECT TRY_CONVERT(bigint,SUBSTRING(RTRIM(BPSNUM_0),2,14)) FROM TEST.BPSUPPLIER WHERE BPSNUM_0 LIKE ''F%'') nums) observed CROSS APPLY(SELECT ''F''+CONVERT(varchar(14),ISNULL(observed.highest,0)+1) AS code) proposal WHERE @Folder=''TEST'' AND c.BSGCOD_0=@Category UNION ALL SELECT ''OB'' AS folder,c.BSGCOD_0,c.CRY_0,c.CUR_0,c.PTE_0,c.VACBPR_0,c.ACCCOD_0,c.REFCOU_0,c.CREMOD_0,CASE WHEN EXISTS(SELECT 1 FROM OB.TABCUR v WHERE v.CUR_0=c.CUR_0) THEN 1 ELSE 0 END AS currency_verified,CASE WHEN EXISTS(SELECT 1 FROM OB.TABCOUNTRY v WHERE v.CRY_0=c.CRY_0) THEN 1 ELSE 0 END AS country_verified,CASE WHEN EXISTS(SELECT 1 FROM OB.TABPAYTERM v WHERE v.PTE_0=c.PTE_0) THEN 1 ELSE 0 END AS payment_verified,CASE WHEN EXISTS(SELECT 1 FROM OB.TABVACBPR v WHERE v.VACBPR_0=c.VACBPR_0 AND v.ENAFLG_0=2) THEN 1 ELSE 0 END AS tax_regime_verified,CASE WHEN EXISTS(SELECT 1 FROM OB.GACCCODE v WHERE v.ACCCOD_0=c.ACCCOD_0 AND v.TYP_0=3) THEN 1 ELSE 0 END AS accounting_verified,CAST(NULL AS varchar(15)) AS candidate_code,CASE WHEN LEN(proposal.code)<=15 AND NOT EXISTS(SELECT 1 FROM OB.BPARTNER p WHERE p.BPRNUM_0=proposal.code) AND NOT EXISTS(SELECT 1 FROM OB.BPSUPPLIER s WHERE s.BPSNUM_0=proposal.code) THEN 0 ELSE 0 END AS candidate_available FROM OB.BPSCATEG c OUTER APPLY (SELECT MAX(n) AS highest FROM (SELECT TRY_CONVERT(bigint,SUBSTRING(RTRIM(BPRNUM_0),2,14)) n FROM OB.BPARTNER WHERE BPRNUM_0 LIKE ''F%'' UNION ALL SELECT TRY_CONVERT(bigint,SUBSTRING(RTRIM(BPSNUM_0),2,14)) FROM OB.BPSUPPLIER WHERE BPSNUM_0 LIKE ''F%'') nums) observed CROSS APPLY(SELECT ''F''+CONVERT(varchar(14),ISNULL(observed.highest,0)+1) AS code) proposal WHERE @Folder=''OB'' AND c.BSGCOD_0=@Category'}
    default {throw 'Unknown SELECT tool'}
   }
}
